-- Catalog 366 SKU từ shared/catalog/products.csv (T-08.2, T-47.1). Owner: LucVT.
-- FILE SINH TỰ ĐỘNG bởi tools/catalog/csv_to_sql.py, không sửa tay.
-- Upsert theo sku: SKU đã có thì cập nhật, SKU mới thì thêm, không xoá SKU nào.

ON CONFLICT (sku) DO UPDATE SET
    name = EXCLUDED.name,
    brand = EXCLUDED.brand,
    category = EXCLUDED.category,
    skin_types = EXCLUDED.skin_types,
    skin_concerns = EXCLUDED.skin_concerns,
    usage_time = EXCLUDED.usage_time,
    ingredients_inci = EXCLUDED.ingredients_inci,
    size_ml = EXCLUDED.size_ml,
    pao_months = EXCLUDED.pao_months,
    price_web = EXCLUDED.price_web,
    price_shopee = EXCLUDED.price_shopee,
    price_tiktok = EXCLUDED.price_tiktok,
    stock = EXCLUDED.stock,
    active = EXCLUDED.active,
    description = EXCLUDED.description,
    barcode = EXCLUDED.barcode,
    source_url = EXCLUDED.source_url,
    image_key = EXCLUDED.image_key,
    image_source_url = EXCLUDED.image_source_url,
    image_license_note = EXCLUDED.image_license_note,
    updated_at = now();
